<?php namespace App\Http\Controllers; use App\Models\{Product,Supplier,Salesperson,StockTransaction,StockHistory}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException; class StockTransactionController extends Controller {private function data(){return ['products'=>Product::where('status','active')->orderBy('name')->get(),'suppliers'=>Supplier::orderBy('name')->get(),'salespeople'=>Salesperson::where('status','active')->orderBy('name')->get()];} public function inbound(){return view('stock.form',$this->data()+['type'=>'in']);} public function outbound(){return view('stock.form',$this->data()+['type'=>'out']);} private function save(Request $r,$type){$d=$r->validate(['transaction_date'=>'required|date','product_id'=>'required|exists:products,id','qty'=>'required|integer|min:1','price'=>'nullable|numeric|min:0','supplier_id'=>'nullable|exists:suppliers,id','salesperson_id'=>'nullable|exists:salespeople,id','reference_no'=>'nullable|max:100','destination'=>'nullable|max:150','notes'=>'nullable|max:2000']);if($type==='in')$r->validate(['supplier_id'=>'required']);else $r->validate(['salesperson_id'=>'required','destination'=>'required|max:150']);DB::transaction(function()use($d,$type,$r){$p=Product::lockForUpdate()->findOrFail($d['product_id']);if($type==='out'&&$p->current_stock<$d['qty'])throw ValidationException::withMessages(['qty'=>"Stok {$p->name} hanya tersedia {$p->current_stock}."]);$t=StockTransaction::create($d+['type'=>$type,'user_id'=>$r->user()->id]);$t->items()->create(['product_id'=>$p->id,'qty'=>$d['qty'],'price'=>$d['price']??$p->cost_price]);$p->current_stock += $type==='in'?$d['qty']:-$d['qty'];$p->save();StockHistory::create(['product_id'=>$p->id,'user_id'=>$r->user()->id,'occurred_at'=>now(),'quantity_in'=>$type==='in'?$d['qty']:0,'quantity_out'=>$type==='out'?$d['qty']:0,'balance'=>$p->current_stock,'activity'=>$type==='in'?'Barang masuk':'Barang keluar','reference_type'=>StockTransaction::class,'reference_id'=>$t->id]);});return redirect()->route('stock.'.($type==='in'?'inbound':'outbound'))->with('success','Transaksi berhasil, stok telah diperbarui.');} public function storeInbound(Request $r){return $this->save($r,'in');} public function storeOutbound(Request $r){return $this->save($r,'out');} public function history(){return view('stock.history',['rows'=>StockHistory::with(['product','user'])->latest('occurred_at')->paginate(20)]);}}
